-- #######################################################################################
-- Übersetzt aus hyprland.conf nach hyprland.lua (neue Lua-Konfigurationssprache von Hyprland)
-- Diese Datei gehört nach ~/.config/hypr/hyprland.lua
-- Hyprland muss danach neu gestartet werden, damit die Lua-Config statt der .conf greift.
-- Refer to the wiki for more information: https://wiki.hypr.land/Configuring/Start/
-- #######################################################################################
-- HINWEIS: Der alte "AUTOGENERATED"-Warnhinweis + "autogenerated = 0" aus der .conf hat
-- in der Lua-Welt keine Entsprechung und wurde daher weggelassen.

------------------
---- MONITORE ----
------------------
-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({ output = "",       mode = "preferred",       position = "auto",    scale = 1.0 })
hl.monitor({ output = "DP-3",     mode = "1920x1080@144",   position = "1920x0", scale = 1.2 })
hl.monitor({ output = "HDMI-A-4", mode = "3840x2160@60",    position = "0x0",    scale = 2 })

-- Zwingt Workspace 1 auf den Samsung (HDMI-A-4)
-- default = true sorgt dafür, dass Hyprland beim Start diesen Monitor fokussiert
hl.workspace_rule({ workspace = "1", monitor = "HDMI-A-4", default = true })
hl.workspace_rule({ workspace = "5", monitor = "DP-3",     default = true })

-- unscale XWayland
hl.config({
    xwayland = {
        force_zero_scaling = true,
    },
})

---------------------
---- MY PROGRAMS ----
---------------------
-- - waybar
-- - wofi
-- - hyprlock
-- - hyprshot
-- - hyprpaper
-- - hypridle
-- - swaync
local browser     = "app.zen_browser.zen"
local terminal    = "kitty"
local fileManager = "dolphin"
local menu        = "wofi --show drun --insensitive"

-------------------
---- AUTOSTART ----
-------------------
-- See https://wiki.hypr.land/Configuring/Basics/Autostart/
-- HINWEIS: In der .conf standen zwei "exec-once"-Blöcke an unterschiedlichen Stellen
-- (oben unter AUTOSTART, und weiter unten kurz vor den Fensterregeln). Für Autostart
-- spielt die Reihenfolge im File keine Rolle, deshalb hier zu einem Block zusammengefasst.
hl.on("hyprland.start", function()
    hl.exec_cmd("nm-applet")
    hl.exec_cmd("waybar & hyprpaper & swaync & hypridle &")
    hl.exec_cmd("sleep 1 && $HOME/.config/wallpaper/script/Random_Wallpaper.sh")

    -- Startet cliphist für Text
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    -- Startet cliphist für Bilder
    hl.exec_cmd("wl-paste --type image --watch cliphist store")

    -- (ehemals weiter unten im File, siehe "WINDOWS AND WORKSPACES")
    hl.exec_cmd("sh -c 'command -v synology-drive >/dev/null 2>&1 && synology-drive'")
    hl.exec_cmd("sleep 2 && xrandr --output HDMI-A-4 --primary")
end)

