hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("HYPRSHOT_DIR", "/home/tobi/Pictures/Screenshots")
hl.env("QT_QPA_PLATFORMTHEME", "qt5ct")
-- ODER (falls du qt6 nutzt, was bei neuerem Dolphin der Fall ist):
-- HINWEIS: das war in deiner .conf schon so (zweimal gesetzt) - der zweite Aufruf
-- überschreibt den ersten, es "gewinnt" also qt6ct. Wenn das nicht gewollt ist,
-- eine der beiden Zeilen löschen.
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

