-- See https://wiki.hypr.land/Configuring/Layouts/Dwindle-Layout/ for more
hl.config({
    dwindle = {
        -- pseudotile = true, -- Master switch for pseudotiling, gebunden an mainMod + P (siehe Keybinds)
        preserve_split = true,
        force_split    = 2,     -- Split new window to the right
        smart_split    = false, -- Splits according to the cursor
    },
})

-- See https://wiki.hypr.land/Configuring/Layouts/Master-Layout/ for more
hl.config({
    master = {
        -- 'master': Das neue Fenster wird zum Hauptfenster (Master).
        -- Das bisherige Master-Fenster rutscht automatisch in den Stack.
        new_status = "master",
        -- Stellt sicher, dass der Master links bleibt und der Stack rechts
        orientation = "left",
        -- Wie viel Platz der Master einnimmt (0.5 = 50%)
        mfact = 0.5,
    },
})

