-- https://wiki.hypr.land/Configuring/Variables/#gestures
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })
-- HINWEIS: "swipe" als direction stand so in deiner .conf. Konnte in der Lua-API-Referenz
-- nicht 1:1 gegenprüfen (dort sind primär horizontal/vertical/left/right/up/down/any
-- dokumentiert) - falls Hyprland beim Start meckert, probier stattdessen direction="any".
hl.gesture({ fingers = 3, direction = "swipe", mods = "SUPER", action = "resize" })
hl.gesture({ fingers = 4, direction = "swipe", action = "move" })

